def countPalindromicPaths(matrix):
    n = len(matrix)
    m = len(matrix[0])

    # dp[i][j] will store the number of palindromic paths ending at (i, j)
    dp = [[0] * m for _ in range(n)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(m):
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]
            dp[i][j] %= MOD

    # Check for palindromic paths
    def is_palindrome(path):
        return path == path[::-1]

    count = 0
